  slug: string;
  name: string;
  city: string;
  stateAbbr: string;
  type: "university" | "college" | "community-college" | "high-school" | "research-lab";
  category?: "R1" | "R2" | "R3" | "M1" | "M2" | "M3" | "B" | "Special" | "STEM-HS" | "Magnet" | "Community";
